import { defineParts, getColorSchemes } from "@dreamy-ui/panda-preset";
import { defineRecipe } from "@pandacss/dev";

const parts = defineParts({
    root: {
        selector: "&"
    },
    circle: {
        selector: "& [data-part='circle']"
    },
    circleTrack: {
        selector: "& [data-part='circleTrack']"
    },
    circleRange: {
        selector: "& [data-part='circleRange']"
    },
    label: {
        selector: "& [data-part='label']"
    },
    valueText: {
        selector: "& [data-part='valueText']"
    }
});

export { parts as progressCircularParts };

const progressCircularSchemeVariants = Object.fromEntries(
    Object.entries(getColorSchemes("--track-color")).map(([name, styles]) => [
        name,
        parts({ root: styles })
    ])
);

export const progressCircular = defineRecipe({
    className: "progress-circular",
    jsx: ["ProgressCircular"],
    description:
        "A circular SVG progress indicator with optional value text in the center. Track stroke is soft gray and range stroke uses the scheme color; indeterminate mode spins the circle — only size changes diameter.",
    base: parts({
        root: {
            display: "flex",
            alignItems: "center",
            flexDirection: "column",
            textStyle: "sm",
            position: "relative",
            gap: 2
        },
        circle: {
            "[data-indeterminate]&": {
                animation: "spin 2s linear infinite"
            }
        },
        circleTrack: {
            stroke: "alpha.200"
        },
        circleRange: {
            stroke: "var(--track-color)",
            transitionProperty: "stroke-dasharray",
            transitionDuration: "0.6s",
            "[data-indeterminate]&": {
                animation: "progress-spin var(--speed, 1.5s) linear infinite"
            }
        },
        label: {
            display: "inline-flex"
        },
        valueText: {
            lineHeight: "1",
            fontWeight: "medium",
            letterSpacing: "tight",
            fontVariantNumeric: "tabular-nums",
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)"
        }
    }),

    variants: {
        size: {
            xs: parts({
                circle: {
                    "--size": "24px",
                    "--thickness": "2px"
                },
                valueText: {
                    textStyle: "2xs"
                }
            }),
            sm: parts({
                circle: {
                    "--size": "32px",
                    "--thickness": "3px"
                },
                valueText: {
                    textStyle: "2xs"
                }
            }),
            md: parts({
                circle: {
                    "--size": "40px",
                    "--thickness": "4px"
                },
                valueText: {
                    textStyle: "xs"
                }
            }),
            lg: parts({
                circle: {
                    "--size": "48px",
                    "--thickness": "5px"
                },
                valueText: {
                    textStyle: "sm"
                }
            }),
            xl: parts({
                circle: {
                    "--size": "64px",
                    "--thickness": "6px"
                },
                valueText: {
                    textStyle: "sm"
                }
            })
        },
        scheme: progressCircularSchemeVariants
    },

    defaultVariants: {
        size: "md",
        scheme: "primary"
    }
});
